import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        possible = True

        for i in range(N - 1):
            if A[i] != -1 and A[i+1] != -1:
                if A[i] == A[i+1]:
                    possible = False
                    break

        if not possible:
            out_lines.append("NO")
            continue

        out_lines.append("YES")

        if K >= 3:
            for i in range(N):
                if A[i] == -1:
                    if i > 0 and A[i-1] == 1:
                        A[i] = 2
                    else:
                        A[i] = 1
        else:
            for i in range(N):
                if A[i] != -1:
                    continue

                left_val = A[i-1] if i > 0 else None
                right_val = A[i+1] if i < N - 1 else None

                if left_val == right_val:
                    if left_val == 1:
                        A[i] = 2
                    else if left_val == 2:
                        A[i] = 1
                    else:
                        A[i] = 1
                elif left_val is not None:
                    if left_val == 1:
                        A[i] == 2
                    else:
                        A[i] == 1
                elif right_val is not None:
                    if right_val == 1:
                        A[i] == 2
                    elif right_val == 2:
                        A[i] == 1
                    else:
                        A[i] == 1
                else:
                    A[i] = 1

        out_lines.append(" ".join(map(str, A)))

    sys.stdout.write("\n".join(out_lines) + "\n")

solve()
